     1	// A small task tracker.
     2	
     3	class Task {
     4	  id: number;
     5	  title: string;
     6	  done: boolean;
     7	
     8	  constructor(id: number, title: string) {
     9	    this.id = id;
    10	    this.title = title;
    11	    this.done = false;
    12	  }
    13	}
    14	
    15	function find(tasks: Task[], id: number): Task | undefined {
    16	  return tasks.find((task) => task.id == id);
    17	}
    18	
    19	function main() {
    20	  const text = Deno.readTextFileSync(Deno.args[0]);
    21	  const tasks: Task[] = [];
    22	  let next_id = 1;
    23	
    24	  for (const line of text.replace(/\n+$/, "").split("\n")) {
    25	    if (line == "") {
    26	      continue;
    27	    }
    28	    const space = line.indexOf(" ");
    29	    const command = space < 0 ? line : line.slice(0, space);
    30	    const rest = space < 0 ? "" : line.slice(space + 1);
    31	
    32	    if (command == "add") {
    33	      tasks.push(new Task(next_id, rest));
    34	      console.log(`added ${next_id}`);
    35	      next_id = next_id + 1;
    36	    } else if (command == "done") {
    37	      const id = Number(rest);
    38	      const task = find(tasks, id);
    39	      if (task === undefined) {
    40	        console.log(`no such task ${id}`);
    41	      } else {
    42	        task.done = true;
    43	        console.log(`done ${id}`);
    44	      }
    45	    } else if (command == "list") {
    46	      for (const task of tasks) {
    47	        if (!task.done) {
    48	          console.log(`${task.id} ${task.title}`);
    49	        }
    50	      }
    51	    }
    52	  }
    53	}
    54	
    55	main();
